def tight_xlims_year(time: xr.DataArray) -> tuple[int, int]:
    """ Take a time axis (number or datetime) and return its min()-1 and max()+1 years. """
    # Find min, max
    tlim = [time.min(), time.max()]

    # Handle datetime objects: Pull out year
    input_is_datetime = hasattr(time, "dt")  # Is datetime-like
    if input_is_datetime:
        tlim = [t.dt.year for t in tlim]

    # Get values and pad
    tlim = [t.values for t in tlim]
    tlim = [tlim[0] - 1, tlim[1] + 1]

    # Convert back to datetime if desired
    if input_is_datetime:
        tlim = [np.datetime64(f"{tlim[0]}-01-01"),
                np.datetime64(f"{tlim[1]}-12-31"),
               ]

    return tlim

